const ICON_1 = 'data:image/png;base64,'; 
const ICON_2 = 'data:image/png;base64,';

const injectButton = () => {
    const optionsMenu = document.querySelector('ytmusic-menu-renderer.ytmusic-player-bar');
    if (!optionsMenu || document.getElementById('discord-btn')) return;

    const btn = document.createElement('button');
    btn.id = 'discord-btn';

    const img = document.createElement('img');
    img.id = 'discord-img';
    img.src = ICON_1;

    img.dataset.state = 'icon1';

    Object.assign(img.style, {
        width: '24px',
        height: '24px',
        pointerEvents: 'none',
        transition: 'transform 0.1s ease-in-out'
    });

    Object.assign(btn.style, {
        background: 'transparent',
        border: 'none',
        cursor: 'pointer',
        padding: '0 10px',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center'
    });

    btn.appendChild(img);

    btn.onclick = () => {
        const { ipcRenderer } = require('electron');

        const currentImg = document.getElementById('discord-img');

        if (currentImg.dataset.state === 'icon1') {
            currentImg.src = ICON_2;
            currentImg.dataset.state = 'icon2';
            console.log("Switched to Icon 2");
            ipcRenderer.send('set-rpc-enabled', false);
            currentImg.style.transform = 'scale(1.2)';
            setTimeout(() => currentImg.style.transform = 'scale(1)', 100);
        } else {
            currentImg.src = ICON_1;
            currentImg.dataset.state = 'icon1';
            console.log("Switched to Icon 1");
            ipcRenderer.send('set-rpc-enabled', true);
            currentImg.style.transform = 'scale(1.2)';
            setTimeout(() => currentImg.style.transform = 'scale(1)', 100);
        }
    };

    optionsMenu.insertAdjacentElement('afterend', btn);
};

setInterval(injectButton, 1000);